<template><NuxtLayout><h1>Patch Panel & Cable Mapping</h1><p class="muted">Connect switch ports to patch panels and other network equipment. Each port can have only one direct cable connection.</p><div class="panel"><h2>New cable connection</h2><div class="fields"><label>From device<select v-model="deviceA"><option value="">Choose device</option><option v-for="d in devices.filter(x=>x.port_count)" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>From port<select v-model="portA"><option value="">Choose port</option><option v-for="p in ports.filter(x=>String(x.device_id)===deviceA)" :key="p.id" :value="String(p.id)">Port {{p.port_number}}</option></select></label><label>To device<select v-model="deviceB"><option value="">Choose device</option><option v-for="d in devices.filter(x=>x.port_count)" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>To port<select v-model="portB"><option value="">Choose port</option><option v-for="p in ports.filter(x=>String(x.device_id)===deviceB)" :key="p.id" :value="String(p.id)">Port {{p.port_number}}</option></select></label><label>Cable label<input v-model="label" placeholder="CAB-001"></label><label>Cable type<select v-model="cableType"><option>Cat5e</option><option>Cat6</option><option>Cat6A</option><option>Fibre SM</option><option>Fibre MM</option><option>DAC</option><option>Other</option></select></label></div><p v-if="error" class="error">{{error}}</p><button :disabled="!editable||!portA||!portB" @click="connect">Save connection</button></div><section class="panel"><h2>Connection map</h2><div class="table-wrap"><table><thead><tr><th>Source</th><th></th><th>Destination</th><th>Label</th><th>Type</th><th></th></tr></thead><tbody><tr v-for="c in connections" :key="c.id"><td><strong>{{c.a_device}}</strong> · Port {{c.a_number}}</td><td>⟷</td><td><strong>{{c.b_device}}</strong> · Port {{c.b_number}}</td><td>{{c.cable_label||'—'}}</td><td>{{c.cable_type}}</td><td><button :disabled="!editable" @click="remove(c.id)">Disconnect</button></td></tr></tbody></table></div><p v-if="!connections.length" class="muted">No connections recorded yet.</p></section><div v-if="disconnectTarget !== null" class="iv-modal-backdrop" @click.self="closeDisconnect" @keydown.esc="closeDisconnect"><section class="iv-modal" role="dialog" aria-modal="true" aria-labelledby="iv-disconnect-title" tabindex="-1"><h2 id="iv-disconnect-title">Disconnect cable?</h2><p>Are you sure you want to remove this connection? This action cannot be undone.</p><p v-if="disconnectError" class="error">{{ disconnectError }}</p><div class="iv-modal-actions"><button type="button" :disabled="disconnectBusy" @click="closeDisconnect">Cancel</button><button type="button" :disabled="disconnectBusy" @click="confirmDisconnect">{{ disconnectBusy ? 'Disconnecting…' : 'Disconnect' }}</button></div></section></div></NuxtLayout></template><script setup lang="ts">const auth=useAuth(),editable=computed(()=>['admin','editor'].includes(auth.value?.role));const {data:devices}=await useFetch<any[]>('/api/devices',{default:()=>[]});const {data:ports}=await useFetch<any[]>('/api/ports',{default:()=>[]});const {data:connections,refresh}=await useFetch<any[]>('/api/connections',{default:()=>[]});const deviceA=ref(''),deviceB=ref(''),portA=ref(''),portB=ref(''),label=ref(''),cableType=ref('Cat6'),error=ref('');watch(deviceA,()=>portA.value='');watch(deviceB,()=>portB.value='');async function connect(){error.value='';try{await $fetch('/api/connections',{method:'POST',body:{port_a_id:Number(portA.value),port_b_id:Number(portB.value),cable_label:label.value,cable_type:cableType.value}});portA.value='';portB.value='';label.value='';await refresh()}catch(e:any){error.value=e?.data?.statusMessage||'Could not connect ports'}}const disconnectTarget=ref<number|null>(null),disconnectBusy=ref(false),disconnectError=ref('');function remove(id:number){disconnectError.value='';disconnectTarget.value=id}function closeDisconnect(){if(!disconnectBusy.value)disconnectTarget.value=null}async function confirmDisconnect(){if(disconnectTarget.value===null||disconnectBusy.value)return;disconnectBusy.value=true;disconnectError.value='';try{await $fetch(`/api/connections/${disconnectTarget.value}`,{method:'DELETE'});await refresh();disconnectTarget.value=null}catch(e:any){disconnectError.value=e?.data?.statusMessage||'Could not disconnect'}finally{disconnectBusy.value=false}}</script>
<style scoped>
.iv-modal-backdrop{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;padding:20px}.iv-modal{width:min(100%,460px);padding:24px;border-radius:14px;border:1px solid #40566c;background:#152436;color:#f3f7fc;box-shadow:0 20px 65px rgba(0,0,0,.5)}.iv-modal h2{margin:0 0 12px}.iv-modal p{line-height:1.5}.iv-modal-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:24px}.iv-modal-actions button{min-width:95px}.iv-modal-actions button:last-child{background:#b42332;color:white;border-color:#b42332}.iv-modal-actions button:disabled{opacity:.6;cursor:wait}
</style>
